Solution B: function generateAndSolveMaze(canvasId, width, height) {
  const canvas = document.getElementById(canvasId);
  const ctx = canvas.getContext("2d");
  canvas.setAttribute("width", width);
  canvas.setAttribute("height", height);

  const visited = [];
  const openList = [];

  function generateMaze(x, y, size) {
    if (size < 1) return;
    visited.push({ x, y });

    while (true) {
      let hasNeighbors = false;
      if (x > 1 && !visited.some(node => node.x === x - 1 && node.y === y)) {
        hasNeighbors = true;
        break;
      }
      if (x < width - 2 && !visited.some(node => node.x === x + 1 && node.y === y)) {
        hasNeighbors = true;
        break;
      }
      if (y > 1 && !visited.some(node => node.x === x && node.y === y - 1)) {
        hasNeighbors = true;
        break;
      }
      if (y < height - 2 && !visited.some(node => node.x === x && node.y === y + 1)) {
        hasNeighbors = true;
        break;
      }
      if (hasNeighbors) break;
    }

    let nextX, nextY;
    do {
      if (Math.random() < 0.5) {
        nextX = x - 1;
        nextY = y;
      } else {
        nextX = x + 1;
        nextY = y;
      }
    } while (visited.some(node => node.x === nextX && node.y === nextY))
    generateMaze(nextX, nextY, size - 2);
    do {
      if (Math.random() < 0.5) {
        nextX = x;
        nextY = y - 1;
      } else {
        nextX = x;
        nextY = y + 1;
      }
    } while (visited.some(node => node.x === nextX && node.y === nextY))
    generateMaze(nextX, nextY, size - 2);

    draw(x, y, "#ff0000");
  }

  function draw(x, y, color) {
    ctx.fillStyle = color;
    ctx.fillRect(x * 10, y * 10, 10, 10);
  }

  function solveMaze(startX, startY) {
    const frontier = [{ x: startX, y: startY }];
    let last = null;

    while (frontier.length > 0) {
      last = frontier.shift();
      if (last.x === width - 1 && last.y === height - 1) {
        return last;
      }
      draw(last.x, last.y, "#0000ff");
      if (last.x > 0 && !openList.some(node => node.x === last.x - 1 && node.y === last.y)) {
        openList.push({ x: last.x - 1, y: last.y });
      }
      if (last.x < width - 1 && !openList.some(node => node.x === last.x + 1 && node.y === last.y)) {
        openList.push({ x: last.x + 1, y: last.y });
      }
      if (last.y > 0 && !openList.some(node => node.x === last.x && node.y === last.y - 1)) {
        openList.push({ x: last.x, y: last.y - 1 });
      }
      if (last.y < height - 1 && !openList.some(node => node.x === last.x && node.y === last.y + 1)) {
        openList.push({ x: last.x, y: last.y + 1 });
      }
    }
    return null;
  }

  draw.bind(ctx)(0, 0, "#ffffff");
  generateMaze(width / 2, height / 2, Math.min(width, height));
  const end = solveMaze(0, 0);

  let current = end;
  while (current.x !== 0 || current.y !== 0) {
    openList.push(current);
    current = openList
      .filter(node => Math.abs(node.x - current.x) === 1 || Math.abs(node.y - current.y) === 1)
      .reduce((best, node) => best heuristic(node) < node.heuristic(node) ? best : node, { x: 0, y: 0 })
  }
  while (openList.length > 0) {
    current = openList.shift();
    draw(current.x, current.y, "#00ff00");
  }
}

